import React,{useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Upload,FileText,Sparkles,Download,Target,ShieldCheck,BrainCircuit,RefreshCw,Plus,Trash2,Briefcase,GraduationCap,Code2,Award,Mail,Phone,MapPin,ExternalLink,ChevronRight,CheckCircle2,AlertTriangle,LayoutTemplate,MessageSquare,Play,ArrowRight,BarChart3,Lightbulb,Lock,Star,Copy,Clock,Send,RotateCcw,Sun,Moon,Camera,Mic,MicOff,Video,VideoOff,Volume2,StopCircle,Check,ChevronDown} from 'lucide-react';
import {FaceLandmarker, PoseLandmarker, FilesetResolver} from '@mediapipe/tasks-vision';
import './styles.css';

const API=import.meta.env.VITE_API_URL||(import.meta.env.DEV?'':'https://rolefit-ai-f126h.onrender.com');
const WS_BASE=(()=>{try{const u=new URL(API||window.location.origin,window.location.href);u.protocol=u.protocol==='https:'?'wss:':'ws:';return u.origin}catch{return `${window.location.protocol==='https:'?'wss':'ws'}://${window.location.host}`}})();
const demoResume=`Aarav Sharma\nSoftware Engineer\naarav.sharma@email.com | +91 9876543210 | Hyderabad, India\nLinkedIn: linkedin.com/in/aaravsharma | GitHub: github.com/aaravsharma\n\nSUMMARY\nSoftware engineer building backend and AI-powered web applications.\n\nSKILLS\nPython, FastAPI, JavaScript, React, SQL, PostgreSQL, AWS, Git, REST APIs, Docker\n\nEXPERIENCE\nSoftware Engineering Intern — TechNova\nJun 2025 - Aug 2025\nBuilt REST APIs using Python and FastAPI. Worked with PostgreSQL and AWS services. Collaborated with a team using Git and agile development.\n\nPROJECTS\nWeather Intelligence Platform\nBuilt a FastAPI weather application with REST API integration and AI-powered recommendations.\n\nEDUCATION\nB.Tech Computer Science and Engineering — 2024-2028\n\nCERTIFICATIONS\nAWS Cloud Practitioner Essentials`;
const demoJD=`Backend Software Engineer\n\nWe are looking for a Backend Software Engineer to design, develop, and maintain scalable backend services and REST APIs.\n\nRequired Qualifications\n- Strong proficiency in Python.\n- Experience with FastAPI or similar Python web frameworks.\n- Strong understanding of REST API development.\n- Experience with SQL and PostgreSQL.\n- Hands-on experience with AWS.\n- Experience with Docker and containerized applications.\n- Familiarity with Kubernetes.\n- Understanding of CI/CD pipelines.\n- Proficiency with Git and collaborative software development.\n- Strong problem-solving and communication skills.\n- Bachelor's degree in Computer Science.\n\nPreferred\n- Microservices architecture\n- Redis or Kafka\n- Automated testing\n- Observability and application monitoring\n- AI-powered applications`;
const templates=[
 {id:'jake',name:"Jake's Resume",tag:'Source',desc:'Compact single-column engineering layout based on the supplied LaTeX source.'},
 {id:'faangpath',name:'FAANGPath',tag:'Source',desc:'ATS-friendly engineering layout based on the supplied FAANGPath source.'},
 {id:'awesome',name:'Awesome-CV',tag:'Source',desc:'Polished professional layout based on the supplied Awesome-CV class.'},
 {id:'rendercv',name:'RenderCV',tag:'Source',desc:'Clean structured layout based on the supplied RenderCV source.'},
 {id:'deedy',name:'RoleFit Two-Column',tag:'RoleFit',desc:'Dense two-column technical layout for projects and skills.'},
 {id:'classic',name:'RoleFit Classic ATS',tag:'ATS+',desc:'Traditional single-column layout optimized for readability.'},
 {id:'modern',name:'RoleFit Modern',tag:'ATS+',desc:'Clean contemporary layout with generous spacing.'}
];
function Score({label,value,sub}){return <div className="score-card"><div className="score-ring"><span>{value}</span></div><div><div className="muted">{label}</div><strong>{sub}</strong></div></div>}
function Badge({children,tone=''}){return <span className={'badge '+tone}>{children}</span>}
function App(){
 const [tab,setTab]=useState('analyzer'),[resume,setResume]=useState(''),[jd,setJd]=useState(''),[file,setFile]=useState(null),[analysis,setAnalysis]=useState(null),[optimized,setOptimized]=useState(null),[selected,setSelected]=useState([]),[loading,setLoading]=useState(false),[error,setError]=useState('');
 const [builder,setBuilder]=useState({name:'',title:'',email:'',phone:'',location:'',linkedin:'',github:'',summary:'',skills:'',educationSchool:'',educationDegree:'',educationField:'',educationStart:'',educationEnd:'',educationGrade:'',experience:'',projects:'',projectGithub:'',projectDemo:'',certifications:''});
 const [template,setTemplate]=useState('jake'),[theme,setTheme]=useState(()=>localStorage.getItem('rolefit-theme')||'light');
 const [interview,setInterview]=useState(null),[answer,setAnswer]=useState(''),[interimTranscript,setInterimTranscript]=useState(''),[interviewDone,setInterviewDone]=useState(false),[evalLoading,setEvalLoading]=useState(false),[interviewScores,setInterviewScores]=useState([]),[interviewHistory,setInterviewHistory]=useState([]),[listening,setListening]=useState(false),[cameraOn,setCameraOn]=useState(false),[micGranted,setMicGranted]=useState(false),[cameraGranted,setCameraGranted]=useState(false),[speaking,setSpeaking]=useState(false),[interviewLoading,setInterviewLoading]=useState(false);
 const videoRef=useRef(null),streamRef=useRef(null),audioContextRef=useRef(null),faceLandmarkerRef=useRef(null),poseLandmarkerRef=useRef(null),visionTimerRef=useRef(null),visionSamplesRef=useRef([]);
 const [visionLive,setVisionLive]=useState(false),[visionMetrics,setVisionMetrics]=useState({facial:0,eyeContact:0,posture:0,bodyMovement:0,communication:0}),[visionReady,setVisionReady]=useState(false); const currentResume=optimized?.optimized_text||optimized?.text||resume;
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('rolefit-theme',theme)},[theme]);
 const loadDemo=()=>{setResume(demoResume);setJd(demoJD);setAnalysis(null);setOptimized(null);setSelected([]);setError('');setTab('analyzer')};
 const analyzeNow=async()=>{if(!resume.trim()||!jd.trim())return setError('Add your resume and target job description first.');setLoading(true);setError('');try{const r=await fetch(`${API}/api/analyze`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resume_text:resume,job_description:jd})});if(!r.ok){const msg=await r.text().catch(()=>`HTTP ${r.status}`);throw Error(msg||`HTTP ${r.status}`)}setAnalysis(await r.json());setOptimized(null)}catch(e){console.error('Analyze error:',e);setError(e?.message?`Analyze failed: ${e.message}`:'Backend is not reachable. Start FastAPI and check VITE_API_URL.')}finally{setLoading(false)}};
 const toggleRec=id=>setSelected(x=>x.includes(id)?x.filter(y=>y!==id):[...x,id]);
 const optimize=async()=>{if(!analysis)return;const recs=analysis.recommendations.filter(x=>selected.includes(x.id)).map(x=>x.title+' — '+x.detail);setLoading(true);try{const r=await fetch(`${API}/api/optimize`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resume_text:resume,job_description:jd,selected_recommendations:recs})});if(!r.ok){const msg=await r.text().catch(()=>`HTTP ${r.status}`);throw Error(msg||`HTTP ${r.status}`)}setOptimized(await r.json())}catch(e){console.error('Optimize error:',e);setError(e?.message?`Optimization failed: ${e.message}`:'Optimization failed. Check the backend and Gemini configuration.')}finally{setLoading(false)}};
 const downloadTemplate=async(t)=>{try{const r=await fetch(`${API}/api/resume/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resume_text:currentResume,template:t,filename:'RoleFit_AI_Resume'})});if(!r.ok)throw Error();const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`RoleFit_AI_${t}.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}catch(e){setError('Could not generate DOCX. Make sure the backend is running.')}};
 const handleFile=async e=>{const f=e.target.files?.[0];if(!f)return;setFile(f);setLoading(true);try{if(f.type==='text/plain'){setResume(await f.text())}else{const fd=new FormData();fd.append('file',f);const r=await fetch(`${API}/api/resume/parse`,{method:'POST',body:fd});if(!r.ok)throw Error();const d=await r.json();setResume(d.text||'')}}catch(e){setError('Could not parse this file. PDF and DOCX parsing requires the backend.')}finally{setLoading(false)}};
 const buildText=()=>{const b=builder;const education=[b.educationSchool,b.educationDegree,b.educationField,[b.educationStart,b.educationEnd].filter(Boolean).join(' - '),b.educationGrade?'Grade: '+b.educationGrade:''].filter(Boolean).join(' | ');const projects=[b.projects,b.projectGithub?'GitHub: '+b.projectGithub:'',b.projectDemo?'Demo: '+b.projectDemo:''].filter(Boolean).join('\n');return `${b.name||'Candidate'}\n${b.title}\n${[b.email,b.phone,b.location].filter(Boolean).join(' | ')}\n${b.linkedin?'LinkedIn: '+b.linkedin:''} ${b.github?'| GitHub: '+b.github:''}\n\nSUMMARY\n${b.summary}\n\nSKILLS\n${b.skills}\n\nEXPERIENCE\n${b.experience}\n\nPROJECTS\n${projects}\n\nEDUCATION\n${education}\n\nCERTIFICATIONS\n${b.certifications}`.replace(/\n{3,}/g,'\n\n')};
 const useBuilder=()=>{const t=buildText();setResume(t);setTab('analyzer');setAnalysis(null)};
 const setupMedia=async()=>{if(!navigator.mediaDevices?.getUserMedia){setError('Camera and microphone are required for the live Mock Interview. Use Chrome or Edge and allow both permissions.');return false}try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});streamRef.current=s;setMicGranted(s.getAudioTracks().some(t=>t.readyState==='live'));setCameraGranted(s.getVideoTracks().some(t=>t.readyState==='live'));setCameraOn(s.getVideoTracks().some(t=>t.readyState==='live'));return true}catch(e){setMicGranted(false);setCameraGranted(false);setCameraOn(false);setError('Camera/microphone permission was denied. Allow both permissions to enter the live Mock Interview.');return false}};
 const stopMedia=()=>{setListening(false);if(visionTimerRef.current)clearInterval(visionTimerRef.current);visionTimerRef.current=null;setVisionLive(false);streamRef.current?.getTracks().forEach(t=>t.stop());streamRef.current=null;setCameraOn(false);setCameraGranted(false);setMicGranted(false)};
 const initVision=async()=>{try{const vision=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@1.0.1/wasm');const [face,pose]=await Promise.all([FaceLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task',delegate:'GPU'},runningMode:'VIDEO',numFaces:1,outputFaceBlendshapes:true}),PoseLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/latest/pose_landmarker_lite.task',delegate:'GPU'},runningMode:'VIDEO',numPoses:1})]);faceLandmarkerRef.current=face;poseLandmarkerRef.current=pose;setVisionReady(true);return true}catch(e){console.warn('Vision models unavailable',e);setVisionReady(false);return false}};
 const startVision=async()=>{if(!cameraOn||!videoRef.current)return;const ready=faceLandmarkerRef.current&&poseLandmarkerRef.current?true:await initVision();if(!ready)return;visionSamplesRef.current=[];setVisionLive(true);if(visionTimerRef.current)clearInterval(visionTimerRef.current);visionTimerRef.current=setInterval(()=>{const v=videoRef.current;if(!v||v.readyState<2)return;try{const now=performance.now();const fr=faceLandmarkerRef.current.detectForVideo(v,now);const po=poseLandmarkerRef.current.detectForVideo(v,now);let facial=70,eyeContact=65,posture=65,bodyMovement=75;const lm=fr.faceLandmarks?.[0];const bs=fr.faceBlendshapes?.[0]?.categories||[];const get=(n)=>bs.find(x=>x.categoryName===n)?.score||0;if(lm){const smile=Math.max(get('mouthSmileLeft'),get('mouthSmileRight'));const eyeOpen=(get('eyeBlinkLeft')+get('eyeBlinkRight'))/2;const brow=(get('browOuterUpLeft')+get('browOuterUpRight'))/2;facial=Math.round(Math.max(0,Math.min(100,55+smile*30+(1-eyeOpen)*12+brow*8)));const left=lm[33],right=lm[263],nose=lm[1];const cx=(left.x+right.x)/2;const span=Math.max(.01,Math.abs(right.x-left.x));const gazeOffset=Math.abs((nose.x-cx)/span);eyeContact=Math.round(Math.max(0,Math.min(100,100-gazeOffset*170)));}const pl=po.landmarks?.[0];if(pl){const ls=pl[11],rs=pl[12],lh=pl[23],rh=pl[24];const shoulderTilt=Math.abs(ls.y-rs.y);const shoulderCenter=(ls.y+rs.y)/2,hipCenter=(lh.y+rh.y)/2;posture=Math.round(Math.max(0,Math.min(100,100-shoulderTilt*300-Math.abs((shoulderCenter-hipCenter)-0.25)*80)));const prev=visionSamplesRef.current.at(-1);if(prev){const motion=Math.abs(ls.x-prev.lsx)+Math.abs(rs.x-prev.rsx)+Math.abs(ls.y-prev.lsy)+Math.abs(rs.y-prev.rsy);bodyMovement=Math.round(Math.max(0,Math.min(100,100-motion*180)));}visionSamplesRef.current.push({lsx:ls.x,rsx:rs.x,lsy:ls.y,rsy:rs.y});if(visionSamplesRef.current.length>20)visionSamplesRef.current.shift();}setVisionMetrics(x=>({...x,facial,eyeContact,posture,bodyMovement}));}catch(e){console.warn('Vision frame skipped',e)}},500)};
 const visionSnapshot=()=>{const v=visionMetrics;const communication=Math.max(0,Math.min(100,Math.round((v.facial*.15+v.eyeContact*.2+v.posture*.2+v.bodyMovement*.1+v.communication*.35)||0)));return {...v,communication,overallPresentation:Math.round(v.facial*.2+v.eyeContact*.2+v.posture*.2+v.bodyMovement*.1+v.communication*.3)}};

 useEffect(()=>{if(!cameraOn||!streamRef.current||!videoRef.current)return;const video=videoRef.current;video.srcObject=streamRef.current;video.muted=true;video.playsInline=true;const attach=async()=>{try{await video.play();await startVision()}catch(e){console.warn('Camera preview could not autoplay:',e)}};if(video.readyState>=1)attach();else video.onloadedmetadata=attach;return()=>{video.onloadedmetadata=null}},[cameraOn,interview]);
 useEffect(()=>()=>{streamRef.current?.getTracks().forEach(t=>t.stop());},[]);
 const startInterview=async()=>{if(!currentResume.trim()||!jd.trim())return setError('Load a resume and job description before starting the interview.');try{const AC=window.AudioContext||window.webkitAudioContext;if(AC&&!audioContextRef.current)audioContextRef.current=new AC();await audioContextRef.current?.resume?.()}catch(e){console.warn('AudioContext activation warning:',e)}setInterviewLoading(true);setInterviewDone(false);setInterviewScores([]);setInterviewHistory([]);setAnswer('');setInterimTranscript('');setError('');setTab('interview');try{await setupMedia();const r=await fetch(`${API}/api/interview/start`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resume_text:currentResume,job_description:jd,question_count:12})});if(!r.ok){const msg=await r.text().catch(()=>`HTTP ${r.status}`);throw Error(msg||`HTTP ${r.status}`)}const d=await r.json();const first=d.questions?.[0]||{};const normalized={...d,question:d.question||first.question||'',round:d.round||first.round||'Introduction',index:0,progress:1,total:d.total||d.questions?.length||12};setInterview(normalized)}catch(e){console.error('Interview start error:',e);setError(e?.message?`Could not start interview: ${e.message}`:'Could not start interview. Check the backend.')}finally{setInterviewLoading(false)}};
 const communicationSnapshot=(text)=>{const words=(text.trim().match(/\b[\w']+\b/g)||[]).length;const fillers=(text.match(/\b(um|uh|like|actually|basically|you know)\b/gi)||[]).length;const lengthScore=Math.min(100,45+Math.min(45,words*1.2));return Math.max(0,Math.min(100,Math.round(lengthScore-fillers*5))) };
 const submitAnswer=async()=>{if(!interview||!answer.trim())return;setVisionMetrics(x=>({...x,communication:communicationSnapshot(answer)}));setEvalLoading(true);try{const r=await fetch(`${API}/api/interview/evaluate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:interview.question,answer:answer,resume_text:currentResume,job_description:jd,round_name:interview.round,vision_metrics:{...visionSnapshot(),communication:communicationSnapshot(answer)}})});if(!r.ok){const msg=await r.text().catch(()=>`HTTP ${r.status}`);throw Error(msg||`HTTP ${r.status}`)}const d=await r.json();const record={round:interview.round,question:interview.question,answer,score:Number(d.score)||0,feedback:d.feedback||'',improvement:d.improvement||'',vision:d.presentation||visionSnapshot()};const nextScores=[...interviewScores,record];setInterviewScores(nextScores);setInterviewHistory(nextScores);setAnswer('');setInterimTranscript('');const nextIndex=(interview.index??0)+1;if(nextIndex>=interview.total){setInterviewDone(true);await finishInterview(nextScores);return}const nextQuestion=interview.questions[nextIndex];const nextState={...interview,index:nextIndex,progress:nextIndex+1,question:nextQuestion.question,round:nextQuestion.round,difficulty:nextQuestion.difficulty};setInterview(nextState);setTimeout(()=>{},200)}catch(e){console.error('Interview evaluation error:',e);setError(e?.message?`Could not evaluate answer: ${e.message}`:'Could not evaluate answer. You can retry this question.')}finally{setEvalLoading(false)}};
 const finishInterview=async(records)=>{try{const r=await fetch(`${API}/api/interview/final`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resume_text:currentResume,job_description:jd,history:records})});if(r.ok){const d=await r.json();setInterview(x=>({...x,final:d}))}}catch(e){console.error('Final interview review error:',e)}finally{stopMedia();}};
 const restartInterview=()=>{stopMedia();try{audioContextRef.current?.close?.()}catch{}audioContextRef.current=null;setInterview(null);setInterviewDone(false);setInterviewScores([]);setInterviewHistory([]);setAnswer('');setInterimTranscript('');setError('')};
 const final=interview?.final; const avg=interviewScores.length?Math.round(interviewScores.reduce((a,x)=>a+(Number(x.score)||0),0)/interviewScores.length):0;
 return <div className="app">
  <header className="topbar"><div className="brand"><div className="logo"><Sparkles size={19}/></div><div><b>Role<span>Fit-AI</span></b><small>AI Career Intelligence</small></div></div><nav><button className={tab==='analyzer'?'active':''} onClick={()=>setTab('analyzer')}>Analyzer</button><button className={tab==='builder'?'active':''} onClick={()=>setTab('builder')}><LayoutTemplate size={15}/> Resume Builder</button><button className={tab==='interview'?'active':''} onClick={()=>setTab('interview')}><MessageSquare size={15}/> Mock Interview</button></nav><div className="top-actions"><div className="trust"><ShieldCheck size={14}/> ATS-aware</div><button className="theme-toggle" title="Toggle theme" onClick={()=>setTheme(theme==='light'?'dark':'light')}>{theme==='light'?<Moon size={17}/>:<Sun size={17}/>}<span>{theme==='light'?'Dark':'Light'}</span></button></div></header>
  {error&&<div className="errorbar"><AlertTriangle size={15}/>{error}<button onClick={()=>setError('')}>×</button></div>}
  {tab==='analyzer'&&<><section className="hero"><div><Badge tone="purple">AI-POWERED CAREER COPILOT</Badge><h1>Make your resume <span>match the role.</span><br/>Then practice the interview.</h1><p>Semantic job matching, ATS diagnostics, selected AI recommendations, professional resume templates and a role-specific face-to-face mock interview.</p><div className="hero-actions"><button className="primary" onClick={loadDemo}><Play size={16}/> Try live demo</button><button className="ghost" onClick={()=>document.getElementById('workspace').scrollIntoView({behavior:'smooth'})}>Start with my resume <ArrowRight size={16}/></button></div></div><div className="hero-visual"><div className="floating-card"><div className="tiny">LIVE DEMO MATCH</div><strong>{analysis?.match_score!=null?analysis.match_score+'%':'—'}</strong><div className="bar"><i style={{width:'84%'}}/></div><small>Skills + semantic context</small></div><div className="floating-card right"><div className="tiny">LIVE DEMO ATS</div><strong>{analysis?.ats_score!=null?analysis.ats_score:'—'}<span>/100</span></strong><div className="mini-tags"><Badge>Keywords</Badge><Badge>Format</Badge><Badge>Structure</Badge></div></div><div className="hero-orb"><BrainCircuit size={56}/></div></div></section>
  <section id="workspace" className="workspace"><div className="section-head"><div><Badge>01 · ANALYZE</Badge><h2>Resume + target role</h2><p>Upload a resume, paste a job description, then inspect the evidence before changing anything.</p></div><button className="ghost" onClick={loadDemo}><RefreshCw size={15}/> Load demo here</button></div><div className="input-grid"><div className="panel"><div className="panel-title"><span><Upload size={16}/> Resume</span>{file&&<Badge tone="green">{file.name}</Badge>}</div><label className="dropzone"><input type="file" accept=".pdf,.docx,.txt" onChange={handleFile}/><FileText size={30}/><strong>Drop PDF / DOCX / TXT</strong><span>or click to browse</span></label><textarea value={resume} onChange={e=>setResume(e.target.value)} placeholder="Paste resume text here..."/></div><div className="panel"><div className="panel-title"><span><Briefcase size={16}/> Target Job Description</span><Badge>Required</Badge></div><textarea className="jd" value={jd} onChange={e=>setJd(e.target.value)} placeholder="Paste the complete job description here..."/><button className="primary full" onClick={analyzeNow} disabled={loading}>{loading?<><RefreshCw className="spin" size={16}/> Analyzing...</>:<>Analyze Match <ChevronRight size={16}/></>}</button></div></div>
  {analysis&&<><div className="score-grid"><Score label="Overall Match" value={analysis.match_score+'%'} sub="Transparent 0–100 score"/><Score label="ATS Score" value={analysis.ats_score} sub="Parser readiness"/><Score label="Keywords" value={analysis.keyword_coverage+'%'} sub="JD coverage"/><Score label="Skill Fit" value={analysis.skill_coverage+'%'} sub="Required skills"/></div><div className="results-grid"><div className="panel"><div className="panel-title"><span><CheckCircle2 size={16}/> Matched skills</span><Badge tone="green">{analysis.matched_skills.length}</Badge></div><div className="chips">{analysis.matched_skills.map(x=><Badge tone="green" key={x}>{x}</Badge>)}</div><div className="panel-title gap-top"><span><AlertTriangle size={16}/> Missing / weak</span><Badge tone="red">{analysis.missing_skills.length}</Badge></div><div className="chips">{analysis.missing_skills.map(x=><Badge tone="red" key={x}>{x}</Badge>)}</div></div><div className="panel"><div className="panel-title"><span><BarChart3 size={16}/> Match score breakdown</span><Badge tone="purple">0–100</Badge></div>{Object.entries(analysis.match_breakdown||{}).filter(([k])=>k!=="formula").map(([k,v])=><div className="breakdown" key={k}><span>{k} <small className="muted">({v.weight}%)</small></span><strong>{v.score}/100 → {v.points} pts</strong></div>)}<p className="muted formula-note">{analysis.match_breakdown?.formula||'Semantic + required skills + JD keywords'}</p><div className="panel-title gap-top"><span><ShieldCheck size={16}/> ATS breakdown</span></div>{Object.entries(analysis.ats_breakdown).map(([k,v])=><div className="breakdown" key={k}><span>{k}</span><strong>{v}</strong></div>)}</div></div><div className="panel recommendations"><div className="panel-title"><span><Lightbulb size={16}/> AI recommendations</span><Badge tone="purple">Select what is true</Badge></div><p className="muted">Choose recommendations you want the optimizer to apply. RoleFit-AI will not invent skills or achievements.</p>{analysis.recommendations.map(r=><label className={'recommendation '+(selected.includes(r.id)?'selected':'')} key={r.id}><input type="checkbox" checked={selected.includes(r.id)} onChange={()=>toggleRec(r.id)}/><span><strong>{r.title}</strong><small>{r.detail}</small></span><Check size={17}/></label>)}<button className="primary" disabled={!selected.length||loading} onClick={optimize}>{loading?<><RefreshCw className="spin" size={16}/> Optimizing...</>:<>Optimize with selected recommendations <Sparkles size={16}/></>}</button></div></>}
  {optimized&&<div className="panel optimized"><div className="section-head compact"><div><Badge tone="green">OPTIMIZED</Badge><h2>Choose a professional template</h2><p>Your selected changes are ready. Preview and download the same content in different layouts.</p></div><button className="ghost" onClick={()=>setTab('builder')}><LayoutTemplate size={15}/> Open Builder</button></div><div className="template-grid">{templates.map(t=><TemplateCard key={t.id} t={t} active={template===t.id} onSelect={()=>setTemplate(t.id)} onDownload={()=>downloadTemplate(t.id)}/>)}</div><div className="before-after"><div><Badge>BEFORE</Badge><strong>{analysis?.ats_score||0}/100 ATS</strong></div><ArrowRight/><div><Badge tone="green">AFTER</Badge><strong>{optimized.analysis?.ats_score||0}/100 ATS</strong></div></div></div>}</section></>}
  {tab==='builder'&&<Builder builder={builder} setBuilder={setBuilder} template={template} setTemplate={setTemplate} currentResume={currentResume} useBuilder={useBuilder} downloadTemplate={downloadTemplate}/>}
  {tab==='interview'&&<InterviewScreen interview={interview} startInterview={startInterview} videoRef={videoRef} cameraOn={cameraOn} micGranted={micGranted} cameraGranted={cameraGranted} speaking={speaking} interviewDone={interviewDone} scores={interviewScores} final={final} avg={avg} restartInterview={restartInterview} history={interviewHistory} resumeReady={!!currentResume.trim()} jdReady={!!jd.trim()} interviewLoading={interviewLoading} visionLive={visionLive} visionMetrics={visionMetrics} currentResume={currentResume} jobDescription={jd} streamRef={streamRef} audioContextRef={audioContextRef}/>}
 </div>}
