function Builder({builder,setBuilder,template,setTemplate,currentResume,useBuilder,downloadTemplate}){const textFields=[['summary','Professional summary'],['skills','Skills'],['experience','Experience'],['projects','Projects'],['certifications','Certifications']];const set=(k,v)=>setBuilder({...builder,[k]:v});return <section className="builder-page"><div className="section-head"><div><Badge>02 · BUILD</Badge><h2>Resume Builder</h2><p>Structured fields keep alignment predictable while templates control the final document design.</p></div><button className="primary" onClick={useBuilder}><Check size={15}/> Use in Analyzer</button></div><div className="builder-layout"><div className="panel builder-form"><div className="form-grid"><label><span>Full name</span><input value={builder.name} onChange={e=>set('name',e.target.value)} placeholder="Full name"/></label><label><span>Professional title</span><input value={builder.title} onChange={e=>set('title',e.target.value)} placeholder="Professional title"/></label><label><span>Email</span><input value={builder.email} onChange={e=>set('email',e.target.value)} placeholder="Email"/></label><label><span>Phone</span><input value={builder.phone} onChange={e=>set('phone',e.target.value)} placeholder="Phone"/></label><label><span>Location</span><input value={builder.location} onChange={e=>set('location',e.target.value)} placeholder="City, Country"/></label><label><span>LinkedIn</span><input value={builder.linkedin} onChange={e=>set('linkedin',e.target.value)} placeholder="linkedin.com/in/..."/></label><label><span>GitHub</span><input value={builder.github} onChange={e=>set('github',e.target.value)} placeholder="github.com/..."/></label>{textFields.map(([k,l])=><label className="wide" key={k}><span>{l}</span><textarea value={builder[k]} onChange={e=>set(k,e.target.value)} placeholder={`Enter ${l.toLowerCase()}...`}/></label>)}<div className="wide builder-subsection"><strong>Education</strong><div className="form-grid nested"><label><span>School / University</span><input value={builder.educationSchool} onChange={e=>set('educationSchool',e.target.value)} placeholder="University / College"/></label><label><span>Degree</span><input value={builder.educationDegree} onChange={e=>set('educationDegree',e.target.value)} placeholder="B.Tech"/></label><label><span>Field of study</span><input value={builder.educationField} onChange={e=>set('educationField',e.target.value)} placeholder="Computer Science"/></label><label><span>Start date</span><input value={builder.educationStart} onChange={e=>set('educationStart',e.target.value)} placeholder="2024"/></label><label><span>End date</span><input value={builder.educationEnd} onChange={e=>set('educationEnd',e.target.value)} placeholder="2028 / Present"/></label><label><span>Grade</span><input value={builder.educationGrade} onChange={e=>set('educationGrade',e.target.value)} placeholder="CGPA / GPA"/></label></div></div><div className="wide builder-subsection"><strong>Project links</strong><div className="form-grid nested"><label><span>Project GitHub</span><input value={builder.projectGithub} onChange={e=>set('projectGithub',e.target.value)} placeholder="https://github.com/..."/></label><label><span>Project demo</span><input value={builder.projectDemo} onChange={e=>set('projectDemo',e.target.value)} placeholder="https://..."/></label></div></div></div></div><div className="panel builder-preview"><div className="panel-title"><span><LayoutTemplate size={16}/> Template preview</span><Badge>{template}</Badge></div><div className={'paper-preview '+template}><h1>{builder.name||'Your Name'}</h1><h3>{builder.title||'Professional Title'}</h3><p>{[builder.email,builder.phone,builder.location].filter(Boolean).join(' · ')||'email · phone · location'}</p><hr/><h4>SUMMARY</h4><p>{builder.summary||'Your professional summary will appear here.'}</p><h4>SKILLS</h4><p>{builder.skills||'Python · SQL · React · AWS'}</p><h4>EXPERIENCE</h4><p>{builder.experience||'Add your experience and measurable impact.'}</p><h4>EDUCATION</h4><p>{[builder.educationDegree,builder.educationField,builder.educationSchool].filter(Boolean).join(' · ')||'Add education details.'}</p></div></div></div><div className="panel template-section"><div className="panel-title"><span><Star size={16}/> 7 professional templates</span><span className="muted">Overleaf-inspired structure, not just color swaps</span></div><div className="template-grid">{templates.map(t=><TemplateCard key={t.id} t={t} active={template===t.id} onSelect={()=>setTemplate(t.id)} onDownload={()=>downloadTemplate(t.id)}/>)}</div></div></section>}
