 const communicationSnapshot=(text)=>{const words=(text.trim().match(/\b[\w']+\b/g)||[]).length;const fillers=(text.match(/\b(um|uh|like|actually|basically|you know)\b/gi)||[]).length;return Math.max(0,Math.min(100,Math.round(45+Math.min(45,words*1.2)-fillers*5))) };
 const visionSnapshot=()=>{const v=visionMetrics||{};const communication=live(v.communication||0);return {...v,communication,overallPresentation:Math.round(v.facial*.2+v.eyeContact*.2+v.posture*.2+v.bodyMovement*.1+communication*.3)}};
