 const pcmBase64=(float32)=>{const buf=new ArrayBuffer(float32.length*2),view=new DataView(buf);for(let i=0;i<float32.length;i++){const x=Math.max(-1,Math.min(1,float32[i]));view.setInt16(i*2,x<0?x*0x8000:x*0x7fff,true)}let bin='';const u8=new Uint8Array(buf);for(let i=0;i<u8.length;i+=0x8000)bin+=String.fromCharCode(...u8.subarray(i,Math.min(i+0x8000,u8.length)));return btoa(bin)};
 const evaluateAnswer=async(answer,q)=>{const vision={...visionSnapshot(),communication:communicationSnapshot(answer)};try{const r=await fetch(`${import.meta.env.VITE_API_URL||''}/api/interview/evaluate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q.question,answer,resume_text:currentResume,job_description:jobDescription,round_name:q.round,vision_metrics:vision})});if(r.ok){const d=await r.json();return {round:q.round,question:q.question,answer,score:Number(d.score)||0,feedback:d.feedback||'',improvement:d.improvement||'',vision:d.presentation||vision}}}catch(e){console.warn('answer evaluation failed',e)}return {round:q.round,question:q.question,answer,score:0,feedback:'Answer captured for final review.',improvement:'',vision}};
