 const handleTurnComplete=async()=>{const answer=userTurnRef.current.trim();if(!answer||processingRef.current)return;processingRef.current=true;setLiveListening(false);const idx=qIndexRef.current,q=interview?.questions?.[idx];if(!q){processingRef.current=false;return}const record=await evaluateAnswer(answer,q);const next=[...liveScoresRef.current,record];liveScoresRef.current=next;setLiveScores(next);userTurnRef.current='';setUserTranscript('');if(idx>=11){await finish(next);processingRef.current=false;return}const nextQ=interview.questions[idx+1];qIndexRef.current=idx+1;setLiveQuestion(nextQ);setMonkTranscript('');setLiveState(`Question ${idx+2} of 12`);send({type:'text',text:`The candidate finished Question ${idx+1}. Now continue the interview and ask Question ${idx+2} exactly as supplied: ${nextQ.question}`});processingRef.current=false};
 useEffect(()=>{if(!interview||liveDone)return;let cancelled=false;const connect=async()=>{setLiveState('Connecting to Gemini Live…');try{const ws=new WebSocket(`${WS_BASE}/ws/monk-live`);wsRef.current=ws;ws.onopen=()=>{setLiveConnected(true);setLiveState('Live connection ready');send({type:'start',resume_text:currentResume,job_description:jobDescription,questions:interview.questions});};ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.type==='ready'){setLiveState('Mock Interview is live — speak naturally');return}if(m.type==='user_transcript'){userTurnRef.current=m.replace?(m.text||''):(userTurnRef.current+(m.text||''));setUserTranscript(userTurnRef.current);setLiveListening(true);return}if(m.type==='monk_transcript'){setMonkTranscript(t=>(t+(m.text||'')).slice(-1200));return}if(m.type==='audio'){playPcm(m.data,m.mimeType);return}if(m.type==='interrupted'){playSourcesRef.current.forEach(src=>{try{src.stop()}catch{}});playSourcesRef.current.clear();setLiveSpeaking(false);playbackTimeRef.current=0;return}if(m.type==='turn_complete'){handleTurnComplete();return}if(m.type==='error'){setLiveError(m.message||'Gemini Live error');setLiveState('Live connection error');}}catch(err){console.warn('Mock Live message error',err)}};ws.onerror=()=>{setLiveError('Mock Interview could not connect to Gemini Live. Check the backend terminal and Gemini configuration.');setLiveState('Connection error')};ws.onclose=()=>{if(!cancelled)setLiveConnected(false)};}catch(e){setLiveError(e?.message||'Could not start Gemini Live')}};connect();return()=>{cancelled=true;try{wsRef.current?.send(JSON.stringify({type:'close'}));wsRef.current?.close()}catch{};wsRef.current=null;try{processorRef.current?.disconnect();sourceRef.current?.disconnect();}catch{};processorRef.current=null;sourceRef.current=null;if(videoTimerRef.current)clearInterval(videoTimerRef.current)}},[interview?.questions?.length]);
 useEffect(()=>{if(!interview||liveDone||!liveConnected||!streamRef.current||!audioContextRef.current)return;let source,node,sink,dead=false;const ctx=audioContextRef.current;const setup=async()=>{try{await ctx.resume?.();if(!ctx.audioWorklet)throw new Error('AudioWorklet is not supported by this browser.');const base=import.meta.env.BASE_URL||'/';await ctx.audioWorklet.addModule(`${base}pcm-capture-worklet.js`);if(dead)return;source=ctx.createMediaStreamSource(streamRef.current);node=new AudioWorkletNode(ctx,'pcm-capture');sink=ctx.createGain();sink.gain.value=0;node.port.onmessage=e=>{if(wsRef.current?.readyState!==WebSocket.OPEN)return;const input=e.data;if(input instanceof Float32Array){const down=downsample(input,ctx.sampleRate);send({type:'audio',data:pcmBase64(down)})}};source.connect(node);node.connect(sink);sink.connect(ctx.destination);sourceRef.current=source;processorRef.current=node;}catch(e){setLiveError('Microphone streaming could not start: '+e.message)}};setup();return()=>{dead=true;try{node?.disconnect();source?.disconnect();sink?.disconnect()}catch{};processorRef.current=null;sourceRef.current=null}},[liveConnected,interview?.index,liveDone]);
